{
  "results": [
    {
      "server": "atuin",
      "tools": [
        {
          "tool_name": "atuin__atuin_threads_search",
          "description": "Full-text search across the transcripts of the threads (AI coding-agent sessions) Atuin has captured (Claude Code, Codex, opencode, pi). Reach for it when a task points at earlier work ('again', 'still', 'continue', a known issue, what was decided): a previous agent may already have diagnosed or decided it. Finds which thread discussed a topic, hit an error, touched a file, or made a decision — it searches what the user and agent wrote, tool names, and thread titles. Each result gives the thread id, harness, last-active time, title, directory, and the best matching message's number and snippet; pass the id to atuin_threads_read to read around the match. Requires the Atuin daemon with thread capture enabled.",
          "score": 11.889596939086914,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "AtuinThreadsSearchToolCall",
            "type": "object",
            "properties": {
              "terms": {
                "description": "What to look for across captured AI-agent session transcripts (what the user and agent\nwrote, the names of tools used, and session titles), case-insensitive. Sessions with a\nmessage containing every term rank first; if there are none, sessions matching any term\n(as a prefix) are returned instead, and the result says so. The words of one term match\nonly together and in that order, so give each word its own term unless they must be\nadjacent. Use a few distinctive words, e.g. a file name, error text or identifier, not a\nsentence.",
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1
                },
                "minItems": 1
              },
              "limit": {
                "description": "Maximum number of sessions to return, most relevant first.",
                "type": "integer",
                "minimum": 1,
                "maximum": 20,
                "default": 5
              },
              "harness": {
                "description": "Restrict the search to sessions from one AI harness. Omit to search every harness.",
                "anyOf": [
                  {
                    "$ref": "#/$defs/HarnessArg"
                  },
                  {
                    "type": "null"
                  }
                ]
              },
              "cwd": {
                "description": "Only sessions whose working directory is this path or inside it. Relative paths,\nincluding '.', resolve against the current project directory. The result says how many\nmatches the filter left out, and where.",
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              },
              "include_subagents": {
                "description": "Include subagent sessions (spawned by another agent session to do part of its work). Off\nby default: their prompts are written by the agent that spawned them, so they crowd out\nthe sessions a person ran.",
                "type": "boolean",
                "default": false
              },
              "roles": {
                "description": "Match only messages from these roles: 'user' (what the person wrote), 'assistant' (the\nagent's replies and tool calls), 'tool' (tool output), 'harness' (context the harness\ninjected). [\"user\"] finds what people asked for and corrected. Omit for every role.",
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "$ref": "#/$defs/RoleArg"
                }
              }
            },
            "additionalProperties": false,
            "required": [
              "terms"
            ],
            "$defs": {
              "HarnessArg": {
                "description": "A harness named on the command line (`--harness`, `--in`) or in an MCP tool call, so every\nplace that takes one accepts the same names: the ones [`harness_name`] shows, with `claude`\nas a hidden synonym of `claude-code`.\n\nOnly harnesses a capture path can actually produce are offered (see `AnyHarness`): advertising\none without a capture source would return empty for every query.",
                "type": "string",
                "enum": [
                  "claude-code",
                  "codex",
                  "copilot",
                  "grok",
                  "kiro",
                  "opencode",
                  "pi",
                  "omp",
                  "amp"
                ]
              },
              "RoleArg": {
                "description": "Who a message is from, as `roles` filters it.",
                "type": "string",
                "enum": [
                  "user",
                  "assistant",
                  "tool",
                  "harness"
                ]
              }
            }
          }
        },
        {
          "tool_name": "atuin__atuin_threads_list",
          "description": "List captured threads, AI coding-agent sessions (Claude Code, Codex, opencode, pi), most recently active first, optionally only those in a directory (cwd: '.' for this project) or active since a time (since: 'today'). Use it to pick up where the previous thread on this project left off ('continue', 'last time') or to see what agents worked on recently, when you have no specific words to search for. Each entry gives the thread id, harness, last-active time, message count, title, and directory. Requires the Atuin daemon with thread capture enabled.",
          "score": 10.82335090637207,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "AtuinThreadsListToolCall",
            "type": "object",
            "properties": {
              "cwd": {
                "description": "Only sessions whose working directory is this path or inside it. Relative paths,\nincluding '.', resolve against the current project directory, so '.' lists the sessions\nfor this project.",
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              },
              "harness": {
                "description": "Only sessions from this AI harness. Omit for every harness.",
                "anyOf": [
                  {
                    "$ref": "#/$defs/HarnessArg"
                  },
                  {
                    "type": "null"
                  }
                ]
              },
              "since": {
                "description": "Only sessions active at or after this time, e.g. 'today', 'yesterday', '3 days ago',\n'2026-09-01'. Relative dates are in the user's local time.",
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              },
              "limit": {
                "description": "Maximum number of sessions to return, newest first.",
                "type": "integer",
                "minimum": 1,
                "maximum": 50,
                "default": 10
              },
              "include_subagents": {
                "description": "Include subagent sessions (spawned by another agent session to do part of its work). Off\nby default: they are fragments of their parent and usually crowd out the sessions a person\nran. Forks and continuations of a session are always listed, marked with where they came\nfrom.",
                "type": "boolean",
                "default": false
              }
            },
            "additionalProperties": false,
            "$defs": {
              "HarnessArg": {
                "description": "A harness named on the command line (`--harness`, `--in`) or in an MCP tool call, so every\nplace that takes one accepts the same names: the ones [`harness_name`] shows, with `claude`\nas a hidden synonym of `claude-code`.\n\nOnly harnesses a capture path can actually produce are offered (see `AnyHarness`): advertising\none without a capture source would return empty for every query.",
                "type": "string",
                "enum": [
                  "claude-code",
                  "codex",
                  "copilot",
                  "grok",
                  "kiro",
                  "opencode",
                  "pi",
                  "omp",
                  "amp"
                ]
              }
            }
          }
        },
        {
          "tool_name": "atuin__atuin_output_search",
          "description": "Full-text search over the terminal output of every captured command. Use it when you know what was printed but not which command printed it: an error message, a version string, a hostname, a file path, a test name. Each result gives the command (with its history ID, timestamp, directory and exit code) and the numbered output lines around each match; pass the history ID and line numbers to atuin_output to read more. Requires the Atuin daemon with output capture enabled.",
          "score": 9.365341186523438,
          "input_schema": {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "AtuinOutputSearchToolCall",
            "type": "object",
            "properties": {
              "terms": {
                "description": "What to look for in captured command output. Terms are AND-ed and matched as whole words\n(case-insensitive; no regex, no prefix matching), and the words of one term only together\nand in that order, so give each word its own term unless they must be adjacent. Use a few\ndistinctive words from the text you remember, not a sentence, e.g. [\"ENOSPC\"] or\n[\"connection refused\", \"postgres\"].",
                "type": "array",
                "items": {
                  "type": "string",
                  "minLength": 1
                },
                "minItems": 1
              },
              "limit": {
                "description": "Maximum number of commands to return, most relevant first. Fewer may come back even when\nmore would match, so an under-full page does not mean the results are exhausted.",
                "type": "integer",
                "minimum": 1,
                "maximum": 20,
                "default": 5
              },
              "context": {
                "description": "Lines of surrounding output to show on each side of every matching line. 0 shows only the\nmatching lines; raise it when you need more of the surrounding output to understand a\nmatch. Keep it small to avoid flooding the results.",
                "type": "integer",
                "minimum": 0,
                "maximum": 20,
                "default": 1
              }
            },
            "additionalProperties": false,
            "required": [
              "terms"
            ]
          }
        }
      ]
    }
  ],
  "total_hidden_tools": 334,
  "status": "ready",
  "note": null
}

